create or replace function public.seo_comparison_overview(p_older uuid,p_newer uuid,p_category text default '',p_search text default '',p_transition text default '',p_page integer default 0,p_sort text default 'impressions')
returns jsonb language sql stable security invoker set search_path='' as $$
with valid_pair as (
 select exists(select 1 from public.seo_imports a join public.seo_imports b on b.id=p_newer where a.id=p_older and a.status='ready' and b.status='ready' and a.week_start<b.week_start) ok
), a as materialized(select * from public.seo_records where import_id=p_older and status<>'no_data' and (select ok from valid_pair)),
b as materialized(select * from public.seo_records where import_id=p_newer and status<>'no_data' and (select ok from valid_pair)),
paired as (select coalesce(b.key,a.key) key,coalesce(b.query,a.query) query,array(select distinct unnest(coalesce(a.categories,'{}'::text[])||coalesce(b.categories,'{}'::text[])) order by 1) categories,coalesce(a.status,'no_data') old_status,coalesce(b.status,'no_data') new_status,coalesce(a.cannibal,false) old_cannibal,coalesce(b.cannibal,false) new_cannibal,coalesce(a.impressions,0) old_impressions,coalesce(b.impressions,0) new_impressions,coalesce(b.impressions,0)-coalesce(a.impressions,0) delta from a full outer join b using(key)),
scoped_pairs as materialized(select * from paired where p_category='' or p_category=any(categories)),
searched as(select * from scoped_pairs where p_search='' or strpos(key,p_search)>0),
marked as(select *,not old_cannibal and new_cannibal is_new,old_cannibal and not new_cannibal is_resolved,old_status='safe' and new_status='medium' is_safe_medium,old_status='medium' and new_status='danger' is_medium_danger,old_status<>'no_data' and new_status<>'no_data' and old_status<>new_status is_changed from searched),
filtered as(select * from marked where p_transition='' or p_transition='new' and is_new or p_transition='resolved' and is_resolved or p_transition='safe_medium' and is_safe_medium or p_transition='medium_danger' and is_medium_danger or p_transition='changed' and is_changed),
paged as(select key,query,categories,old_status,new_status,old_cannibal,new_cannibal,old_impressions,new_impressions,delta from filtered order by case when p_sort='delta' then abs(delta) end desc nulls last,greatest(old_impressions,new_impressions) desc,key limit 25 offset greatest(p_page,0)*25),
old_categories as(select c name,count(*) total,coalesce(sum(cannibal_impressions) filter(where cannibal),0) affected,count(*) filter(where cannibal) n from a cross join lateral unnest(categories)c group by c),
new_categories as(select c name,count(*) total,coalesce(sum(cannibal_impressions) filter(where cannibal),0) affected,count(*) filter(where cannibal) n from b cross join lateral unnest(categories)c group by c),
taxonomy as(select distinct unnest(categories) name from public.seo_keywords union select name from old_categories union select name from new_categories),
categories as(select t.name,coalesce(o.n,0) old,coalesce(n.n,0) new,coalesce(n.n,0)-coalesce(o.n,0) delta,coalesce(o.total,0) old_total,coalesce(n.total,0) new_total,coalesce(o.affected,0) old_affected,coalesce(n.affected,0) new_affected,coalesce(n.affected,0)-coalesce(o.affected,0) affected_delta from taxonomy t left join old_categories o using(name) left join new_categories n using(name))
select jsonb_build_object('report',jsonb_build_object('category',p_category,'coverage',(select jsonb_build_object('new_common',count(*) filter(where not old_cannibal and new_cannibal and old_status<>'no_data'),'new_only',count(*) filter(where new_cannibal and old_status='no_data'),'resolved_common',count(*) filter(where old_cannibal and not new_cannibal and new_status<>'no_data'),'old_only',count(*) filter(where old_cannibal and new_status='no_data')) from scoped_pairs),'site_old',public.seo_summary(p_older,''),'site_new',public.seo_summary(p_newer,''),'transitions',(select jsonb_build_object('all',count(*),'new',count(*) filter(where not old_cannibal and new_cannibal),'resolved',count(*) filter(where old_cannibal and not new_cannibal),'safe_medium',count(*) filter(where old_status='safe' and new_status='medium'),'medium_danger',count(*) filter(where old_status='medium' and new_status='danger'),'changed',count(*) filter(where old_status<>'no_data' and new_status<>'no_data' and old_status<>new_status)) from scoped_pairs),'flows',coalesce((select jsonb_agg(jsonb_build_object('from',old_status,'to',new_status,'value',n) order by old_status,new_status) from (select old_status,new_status,count(*) n from scoped_pairs where old_status<>'no_data' and new_status<>'no_data' and old_status<>new_status group by old_status,new_status) flow),'[]'::jsonb)),'valid',(select ok from valid_pair),'old',public.seo_summary(p_older,p_category),'new',public.seo_summary(p_newer,p_category),'matched',(select count(*) from searched),'count',(select count(*) from filtered),'rows',coalesce((select jsonb_agg(to_jsonb(paged)) from paged),'[]'::jsonb),'categories',coalesce((select jsonb_agg(to_jsonb(categories) order by abs(delta) desc,name) from categories),'[]'::jsonb),'transitions',(select jsonb_build_object('all',count(*),'new',count(*) filter(where is_new),'resolved',count(*) filter(where is_resolved),'safe_medium',count(*) filter(where is_safe_medium),'medium_danger',count(*) filter(where is_medium_danger),'changed',count(*) filter(where is_changed)) from marked));
$$;
revoke execute on function public.seo_comparison_overview(uuid,uuid,text,text,text,integer,text) from public,anon;
grant execute on function public.seo_comparison_overview(uuid,uuid,text,text,text,integer,text) to authenticated;
